preConditionHook:
// THE 3/10 OSCILLATOR -- Grimes's fast line, in the settled form (merge
// decision 2): the difference of two SIMPLE averages of the close,
//     osc = average of close over fastLen bars, less the average
//           of close over slowLen bars
// with fastLen 3 and slowLen 10 as the book's defaults. Never the MACD word:
// Appendix B spells the construction out as plain moving averages, and the
// chapter 16 restatement in exponential terms loses to it.
// EL's Average RECOMPUTES from scratch every bar (VERIFIED: matched a fresh
// loop on 2,808/2,808 bars; it is NOT a rolling accumulator like the WFSafe_
// wrappers), and Summation adds the newest bar first and works backwards,
// with a single divide at the end -- which is how the loops below run.
// Both averages run over a PRICE expression, which has real bar history, so
// they are recomputed from the bars rather than mirrored; only osc ITSELF is
// a variable, and that is what the ring buffers below mirror.
// The whole quantity is a difference of prices, so it passes the shift test.
// Scratch is declared in localVariables, never at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a
// redefinition when the rule is placed twice in one strategy.
oscFast = 0.0;
for (int i = 0; i < (int)fastLen; ++i) {
    oscFast += close[i];
}
oscFast = oscFast / (int)fastLen;
oscSlow = 0.0;
for (int i = 0; i < (int)slowLen; ++i) {
    oscSlow += close[i];
}
oscSlow = oscSlow / (int)slowLen;
osc = oscFast - oscSlow;
// AN OSCILLATOR JUMP OUT OF PROPORTION: some bar within the last withinBars
// moved the fast line by more than climaxMult times its own recent average
// bar-over-bar change -- an indicator distortion left by a climactic price
// move, after which Grimes says to disregard the oscillator. The natural
// placement is NEGATED, and the book's cooldown is folded into withinBars.
// Identical both sides: a distortion carries no direction.
// osc is an EL VARIABLE, so osc[k] reads the variable's OWN history, which
// holds its initial 0 for every bar before the strategy's first evaluated
// one. Mirrored here as a zero-seeded ring buffer, re-seeded if the depth
// ever changes -- exactly what AwesomeOscillatorSlope, AtrRising and
// BarRangeAboveStd do for the same reason. The rule GUARDS its own warm-up
// on the bar counter instead of comparing against those zeros.
// Three mirrored series, because EasyLanguage reads three variables' own
// histories here: osc (for the one-bar difference), oscJump, and jumpAvg.
if (oscHistory.size() != (std::size_t)2) {
    oscHistory.assign((std::size_t)2, 0.0);
    oscCursor = 0;
}
oscHistory[oscCursor] = osc;
oscCursor = (oscCursor + 1) % oscHistory.size();
oscLag1 = oscHistory[(oscCursor + oscHistory.size() - 2) % oscHistory.size()];
oscJump = std::fabs(osc - oscLag1);
// oscJump's history has to be deep enough for BOTH the climaxLookback
// average taken on this bar and the withinBars scan.
jumpDepth = (int)climaxLookback > (int)withinBars ? (int)climaxLookback : (int)withinBars;
if (jumpDepth < 1) {
    jumpDepth = 1;
}
if (jumpHistory.size() != (std::size_t)jumpDepth) {
    jumpHistory.assign((std::size_t)jumpDepth, 0.0);
    jumpCursor = 0;
}
jumpHistory[jumpCursor] = oscJump;
jumpCursor = (jumpCursor + 1) % jumpHistory.size();
// jumpAvg on THIS bar, summed newest bar first as EL's Summation is.
jumpAvg = 0.0;
for (ii = 0; ii < (int)climaxLookback; ++ii) {
    jumpAvg += jumpHistory[(jumpCursor + jumpHistory.size() - 1 - (std::size_t)ii) % jumpHistory.size()];
}
jumpAvg = jumpAvg / (int)climaxLookback;
// jumpAvg is itself a variable, and the scan reads jumpAvg[ii] -- the value
// the strategy assigned ii bars ago -- so it gets its own mirrored history.
avgDepth = (int)withinBars;
if (avgDepth < 1) {
    avgDepth = 1;
}
if (avgHistory.size() != (std::size_t)avgDepth) {
    avgHistory.assign((std::size_t)avgDepth, 0.0);
    avgCursor = 0;
}
avgHistory[avgCursor] = jumpAvg;
avgCursor = (avgCursor + 1) % avgHistory.size();
jumpFound = false;
for (ii = 0; ii < (int)withinBars; ++ii) {
    double jv = jumpHistory[(jumpCursor + jumpHistory.size() - 1 - (std::size_t)ii) % jumpHistory.size()];
    double av = avgHistory[(avgCursor + avgHistory.size() - 1 - (std::size_t)ii) % avgHistory.size()];
    if (el_gt(jv, climaxMult * av)) {
        jumpFound = true;
    }
}
jumpReady = ctx.CurrentBar() > (int)climaxLookback + (int)withinBars;
